{
  "name": "Wasatch SPI光谱仪",
  "name_en": "Wasatch SPI Spectrometer",
  "manufacturer": "Wasatch Photonics",
  "description": "通过 FT232H USB 转 SPI 转换器通信的 Wasatch 光谱仪，用于触发采集、读取光谱数据，并设置积分时间、探测器增益及 EEPROM/FPGA 相关参数，常用于拉曼或通用光谱测量系统。",
  "description_en": "A Wasatch spectrometer controlled through an FT232H USB-to-SPI interface. It is used to trigger acquisitions, read spectral data, and configure integration time, detector gain, and EEPROM/FPGA-related settings in Raman or general spectroscopy setups.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "初始化并连接 SPI 光谱仪通信。",
      "description_en": "Initialize and connect communication with the SPI spectrometer."
    },
    {
      "action_name": "auto-init_eeprom",
      "description": "从 EEPROM 读取启动参数并初始化本地设置。",
      "description_en": "Load startup parameters from EEPROM and initialize local settings."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与光谱仪的连接。",
      "description_en": "Disconnect from the spectrometer."
    },
    {
      "action_name": "auto-acquire_data",
      "description": "执行一次数据采集，并按需要进行软件平均或 2x2 bin 处理。",
      "description_en": "Perform one data acquisition, with optional software averaging or 2x2 binning."
    },
    {
      "action_name": "auto-set_integration_time_ms",
      "description": "设置积分时间（毫秒）。",
      "description_en": "Set the integration time in milliseconds."
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置探测器增益。",
      "description_en": "Set the detector gain."
    },
    {
      "action_name": "auto-change_setting",
      "description": "更改指定设备设置。",
      "description_en": "Change a specified device setting."
    },
    {
      "action_name": "auto-to_hex",
      "description": "将字节数据格式化为十六进制文本。",
      "description_en": "Format byte data as hexadecimal text."
    },
    {
      "action_name": "auto-check_crc",
      "description": "校验数据的 CRC 校验和。",
      "description_en": "Verify the CRC checksum of data."
    },
    {
      "action_name": "auto-compute_crc",
      "description": "计算数据的 CRC 校验和。",
      "description_en": "Compute the CRC checksum of data."
    },
    {
      "action_name": "auto-fix_crc",
      "description": "重新计算并替换 SPI 命令中的 CRC。",
      "description_en": "Recompute and replace the CRC in an SPI command."
    },
    {
      "action_name": "auto-errorcode_to_string",
      "description": "将设备错误码转换为文本说明。",
      "description_en": "Convert a device error code to a text description."
    },
    {
      "action_name": "auto-validate_write_response",
      "description": "验证 SPI 写命令响应是否有效。",
      "description_en": "Validate whether an SPI write-command response is valid."
    },
    {
      "action_name": "auto-buffer_bytearray",
      "description": "生成适用于 SPI 读写的定长缓冲区。",
      "description_en": "Create a fixed-size buffer for SPI read/write operations."
    },
    {
      "action_name": "auto-decode_read_response",
      "description": "解析并校验 SPI 读取响应数据。",
      "description_en": "Decode and validate SPI read-response data."
    },
    {
      "action_name": "auto-send_command",
      "description": "向设备发送 SPI 命令并读取响应。",
      "description_en": "Send an SPI command to the device and read the response."
    },
    {
      "action_name": "auto-flush_input_buffer",
      "description": "清空 SPI 输入缓冲区。",
      "description_en": "Flush the SPI input buffer."
    },
    {
      "action_name": "auto-wait_for_data_ready",
      "description": "等待设备数据就绪信号。",
      "description_en": "Wait for the device data-ready signal."
    },
    {
      "action_name": "auto-gain_to_ff",
      "description": "将增益值转换为设备使用的 16 位 Funky Float 格式。",
      "description_en": "Convert a gain value to the 16-bit Funky Float format used by the device."
    },
    {
      "action_name": "auto-read_page",
      "description": "读取 EEPROM 页面数据。",
      "description_en": "Read an EEPROM page."
    },
    {
      "action_name": "auto-get_spectrum",
      "description": "获取光谱。",
      "description_en": "Get spectrum."
    }
  ],
  "tag_hints": [
    "Raman spectroscopy",
    "spectral acquisition",
    "SPI communication via FT232H",
    "integration time control",
    "detector gain control",
    "EEPROM configuration",
    "FPGA-based spectrometer"
  ]
}

